export const extraServiceIcons: Record<string, string> = {"group": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"9\" cy=\"7\" r=\"3.5\"/><circle cx=\"17\" cy=\"8\" r=\"2.5\"/><path d=\"M2 21c1-4 3.5-6 7-6s6 2 7 6M15 15c3 0 5.5 1.5 6.5 5\"/></svg>", "trail": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l7 11H5z\"/><path d=\"M12 14v7M8 21h8\"/></svg>", "barn": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21V9l9-6 9 6v12\"/><path d=\"M8 21v-7h8v7\"/></svg>"}
